div.t-att-class:
{
                            'bg-success': this.isReached(option_index),
                            'bg-warning': option_index === this.activeIndex && this.issueCount,
                            'bg-danger': option_index === this.activeIndex && this.hasError,
                            }

span.t-att-class:
{
                            'border-success': this.isReached(option_index),
                            'border-warning': option_index === this.activeIndex && this.issueCount,
                            'border-danger': option_index === this.activeIndex && this.hasError,
                            }
